document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,a="info"){return`\n      <div class="insight-card ${a}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const a=document.getElementById("laundromat-form"),t=document.getElementById("laundromat-result");a&&a.addEventListener("submit",function(a){a.preventDefault();const i=parseInt(document.getElementById("washing-machines").value),o=parseInt(document.getElementById("dryers").value),r=parseFloat(document.getElementById("renovation-cost").value),d=parseFloat(document.getElementById("additional-costs").value),l=parseFloat(document.getElementById("monthly-rent").value),c=parseFloat(document.getElementById("wash-price").value),u=parseFloat(document.getElementById("dry-price").value),p=parseFloat(document.getElementById("utilization").value),v=parseFloat(document.getElementById("utilities").value),m=parseFloat(document.getElementById("maintenance").value),g=parseFloat(document.getElementById("insurance").value),w=parseFloat(document.getElementById("other-expenses").value);if(i<=0||o<=0||p<=0||p>100)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const y=3500,$=2800,h=i*y+o*$+r+d,b=16/1.5,f=p/100,k=i*b*30*f,I=o*b*30*f,E=k*c,F=I*u,B=E+F,M=l+v+m+g+w,x=B-M,D=12*x,P=x/B*100,R=h/x,L=R/12,C=D/h*100,z=E/i,O=F/o;let S="info";x<0?S="warning":P>25&&(S="success");let A="info";C<15?A="warning":C>25&&(A="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>📋 Laundromat Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(h),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(x),`Margin: ${e(P)}`,S)}\n            ${s("⏱️ Payback Period",`${L.toFixed(1)} years`,`${R.toFixed(0)} months`,L<=4?"success":"warning")}\n            ${s("🎯 Annual ROI",e(C),"Return on investment",A)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Washing machines (${i} × $3500)</span>\n                  <span>${n(i*y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Dryers (${o} × $2800)</span>\n                  <span>${n(o*$)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Renovation & setup</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Permits, licenses & other</span>\n                  <span>${n(d)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(h)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Washing (${Math.round(k)} cycles × $${c})</span>\n                  <span>${n(E)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Drying (${Math.round(I)} cycles × $${u})</span>\n                  <span>${n(F)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(B)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Rent</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities (water, electric, gas)</span>\n                  <span>${n(v)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Maintenance & repairs</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Insurance</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(M)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Equipment Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per washer: <strong>${n(z)}/month</strong><br>\n                Revenue per dryer: <strong>${n(O)}/month</strong><br>\n                Utilization rate: <strong>${p}%</strong>\n              </div>\n            </div>\n            <div class="insight-card ${x>0?"success":"warning"}">\n              <h6>📊 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(D)}</strong><br>\n                Weekly profit: <strong>${n(12*x/52)}</strong><br>\n                Daily profit: <strong>${n(x/30)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${P<20?"<li>⚠️ Low profitability. Consider reducing costs or increasing prices.</li>":""}\n              ${p<50?"<li>📍 Low utilization. Improve marketing or choose better location.</li>":""}\n              ${L>5?"<li>⏰ Long payback period. Consider reducing startup costs.</li>":""}\n              ${p>80?"<li>✅ High utilization! Consider expansion or premium pricing.</li>":""}\n              ${P>25?"<li>🎉 Excellent profitability! Consider additional locations.</li>":""}\n              <li>💡 Consider additional revenue streams: vending machines, wash-dry-fold services, WiFi advertising.</li>\n              <li>🔧 Invest in quality equipment to reduce maintenance costs and downtime.</li>\n              <li>📱 Add mobile payments and loyalty programs to increase customer retention and revenue.</li>\n              <li>⏰ Optimize peak hour pricing to maximize revenue during busy periods.</li>\n              <li>🏪 Partner with nearby businesses or apartments for corporate washing services.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.laundryBusinessData={"Washing Machines":i,Dryers:o,"Total Investment ($)":h,"Monthly Revenue ($)":B,"Monthly Expenses ($)":M,"Monthly Profit ($)":x,"Annual Profit ($)":D,"Profit Margin (%)":P,"Annual ROI (%)":C,"Payback Period (years)":L,"Utilization Rate (%)":p}}),window.downloadCSV=function(){if(!window.laundryBusinessData)return;const n=Object.entries(window.laundryBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="laundromat-business-plan.csv",s.click()}});